package com.example.demo;

import java.time.Duration;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Service;

@Service
public class CachedPostService {
    private final StringRedisTemplate redis;
    private final ObjectMapper mapper;
    private final PostApiClient provider;

    public CachedPostService(StringRedisTemplate redis, ObjectMapper mapper,
            PostApiClient provider) {
        this.redis = redis;
        this.mapper = mapper;
        this.provider = provider;
    }

    public PostApiClient.Post read(long id) throws JsonProcessingException {
        if (id < 1) throw new IllegalArgumentException("Positive id required");
        String key = "post:v1:" + id;
        String cached = redis.opsForValue().get(key);
        if (cached != null) {
            return mapper.readValue(cached, PostApiClient.Post.class);
        }
        PostApiClient.Post fresh = provider.read(id);
        redis.opsForValue().set(key, mapper.writeValueAsString(fresh),
                Duration.ofMinutes(5));
        return fresh;
    }
}

package com.example.demo;

import java.net.http.HttpClient;
import java.time.Duration;
import org.springframework.http.MediaType;
import org.springframework.http.client.JdkClientHttpRequestFactory;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestClient;

@Service
public class PostApiClient {
    private final RestClient client;

    public PostApiClient(RestClient.Builder builder) {
        HttpClient http = HttpClient.newBuilder()
                .connectTimeout(Duration.ofSeconds(3)).build();
        var factory = new JdkClientHttpRequestFactory(http);
        factory.setReadTimeout(Duration.ofSeconds(5));
        this.client = builder.baseUrl("https://jsonplaceholder.typicode.com")
                .requestFactory(factory).build();
    }

    public Post read(long id) {
        if (id < 1) throw new IllegalArgumentException("Positive id required");
        Post post = client.get().uri("/posts/{id}", id)
                .retrieve().body(Post.class);
        if (post == null) throw new IllegalStateException("Empty post response");
        return post;
    }

    public Post create(NewPost input) {
        Post post = client.post().uri("/posts")
                .contentType(MediaType.APPLICATION_JSON).body(input)
                .retrieve().body(Post.class);
        if (post == null) throw new IllegalStateException("Empty post response");
        return post;
    }

    public record NewPost(long userId, String title, String body) {}
    public record Post(long userId, long id, String title, String body) {}
}

